from render import *
# These are explicitly chosen rule headings, not inferred from old prose.
R=r'Densitet: \(\rho=m/V\)'
M=r'Massa: \(m=\rho V\)'
V=r'Volym: \(V=m/\rho\)'
B=r'Rätblockets volym: \(V=lbh\)'
C=r'Cylinderns volym: \(V=\pi r^2h\)'
K=r'Klotets volym: \(V=4\pi r^3/3\)'
U=r'Densitetsenheter: \(1\ \mathrm{g/cm^3}=1000\ \mathrm{kg/m^3}\)'
D=r'Densiteten är lutningen: \(\rho=\Delta m/\Delta V\)'
def st(h,tex='',why=''):return (h,(p(why) if why else '')+(m(tex) if tex else ''))
def giv(text):return ('Givet och sökt',p(text))
def ans(tex):return inline(tex)+'.'
def plan(steps,tex):return (steps,ans(tex))
def put(id,steps,tex):setq(id,steps,ans(tex))
def note(h,text):return (h,p(text))
