# Diagramtolkning: separata slutsatser för varje faktiskt efterfrågad del.
def plot80(fit=False):
    # Five measured points, identical scales in the point plot and fitted plot.
    sx=lambda x:55+12*x
    sy=lambda y:245-2.5*y
    out=['<span class="fig"><svg xmlns="http://www.w3.org/2000/svg" width="430" height="310" viewBox="0 0 430 310" role="img" aria-label="Massa som funktion av volym för fem metallbitar"><rect width="430" height="310" fill="white"/>']
    for x in range(0,31,5):
        out.append(f'<path d="M{sx(x)} 35V245" stroke="#dce3e8"/><text x="{sx(x)}" y="267" text-anchor="middle" font-size="13" fill="#263c4b">{x}</text>')
    for y in range(0,81,20):
        out.append(f'<path d="M55 {sy(y)}H415" stroke="#dce3e8"/><text x="45" y="{sy(y)+4}" text-anchor="end" font-size="13" fill="#263c4b">{y}</text>')
    out.append('<path d="M55 30V245H420" fill="none" stroke="#263c4b" stroke-width="2"/><text x="16" y="20" font-size="15" fill="#263c4b">Massa (g)</text><text x="415" y="299" text-anchor="end" font-size="15" fill="#263c4b">Volym (cm³)</text>')
    if fit:out.append(f'<path d="M55 245L{sx(29)} {sy(2.72*29)}" stroke="#b23d36" stroke-width="2.5"/>')
    for x,y in [(5,13),(10,27),(15,41),(20,74),(25,68)]:
        out.append(f'<circle cx="{sx(x)}" cy="{sy(y)}" r="4" fill="#236790"/>')
    return ''.join(out)+'</svg></span>'
